def add_extra_courses():
    migrate()
    created=0
    for spec in COURSES:
        if one('SELECT id FROM courses WHERE title=?',(spec['title'],)):
            continue
        db().execute('INSERT OR IGNORE INTO categories(name) VALUES (?)',(spec['category'],))
        cat=one('SELECT id FROM categories WHERE name=?',(spec['category'],))['id']
        cid=db().execute("INSERT INTO courses(title,description,summary,outcomes,prerequisites,category_id,level,status,cover) VALUES (?,?,?,?,?,?,?,'published',?)",
            (spec['title'],spec['description'],spec['summary'],spec['outcomes'],spec['prerequisites'],cat,spec['level'],spec['cover'])).lastrowid
        for mi,(title,description,lessons) in enumerate(spec['modules']):
            outcomes=f'Понять тему «{title}», применить её в упражнении и объяснить результат.'
            mid=db().execute('INSERT INTO modules(course_id,title,position,description,outcomes) VALUES (?,?,?,?,?)',(cid,title,mi,description,outcomes)).lastrowid
            for li,item in enumerate(lessons):
                lid=db().execute('INSERT INTO lessons(module_id,title,content,minutes,position) VALUES (?,?,?,?,?)',(mid,item[0],item[1],20,li)).lastrowid
                if len(item)>2 and item[2]:
                    qid=db().execute('INSERT INTO quizzes(lesson_id,pass_score) VALUES (?,67)',(lid,)).lastrowid
                    for question in item[2]:
                        db().execute('INSERT INTO questions(quiz_id,text,options,correct,explanation) VALUES (?,?,?,?,?)',
                            (qid,question['text'],json.dumps(question['options'],ensure_ascii=False),json.dumps(question['correct']),question['explanation']))
        last=one('SELECT l.id FROM lessons l JOIN modules m ON m.id=l.module_id WHERE m.course_id=? ORDER BY m.position DESC,l.position DESC LIMIT 1',(cid,))['id']
        title,instructions,kind,criteria=spec['assignment']
        rubric=[{'id':secrets.token_hex(8),'title':name,'max_score':score} for name,score in criteria]
        db().execute('INSERT INTO assignments(lesson_id,title,instructions,rubric,submission_type,max_score,required) VALUES (?,?,?,?,?,100,1)',
            (last,title,instructions,json.dumps(rubric,ensure_ascii=False),kind))
        created+=1
    db().commit()
    return created


def register_extra_course_command(app):
    @app.cli.command('add-extra-courses')
    def add_extra_courses_command():
        """Добавить три содержательных демонстрационных курса без изменения текущих записей."""
        click.echo(f'Добавлено новых практических курсов: {add_extra_courses()}. Повторный запуск безопасен.')
